service.method:

UPDATE SGWGL 
       SET APP_STATUS = ${APP_STATUS} 
     , CURRENT_STAGE  = ${CURRENT_STAGE}  
     , CHANGE_DATE    = ${current.DATE}
     , CHANGE_TIME    = ${current.TIME}
     , CHANGE_USER_ID = ${session.ID}  
 WHERE HOUSE_CODE = ${session.HOUSE_CODE} 
       AND COMPANY_CODE = ${SEPOA_APPROVAL_S_COMPANY_CODE} 
       AND APP_NO = ${APP_NO} 
       AND APP_NO_SEQ = ${APP_NO_SEQ}


UPDATE SGWLN 
       SET APP_LINE_STATUS = ${APP_LINE_STATUS}
     , APP_DEVICE          = ${APP_DEVICE}
     , CHANGE_DATE         = ${current.DATE}
     , CHANGE_TIME         = ${current.TIME}
     , CHANGE_USER_ID      = ${session.ID}  
     , ACCEPT_USER_ID      = ${ACCEPT_USER_ID}
     , ACCEPT_DATE         = ${ACCEPT_DATE} 
     , ACCEPT_TIME         = ${ACCEPT_TIME} 
     , ACCEPT_REASON       = ${ACCEPT_REASON} 
 WHERE HOUSE_CODE = ${session.HOUSE_CODE} 
       AND COMPANY_CODE = ${SEPOA_APPROVAL_S_COMPANY_CODE} 
       AND APP_NO = ${APP_NO} 
       AND APP_NO_SEQ = ${APP_NO_SEQ} 
       AND APP_LINE_SEQ = CASE WHEN ${APP_LINE_SEQ} = 'N'
                          THEN APP_LINE_SEQ
                          ELSE ${APP_LINE_SEQ}
                          END


UPDATE SGWLN 
       SET APP_LINE_STATUS = ${APP_LINE_STATUS}
     , APP_DEVICE          = ${APP_DEVICE}
     , CHANGE_DATE         = ${current.DATE}
     , CHANGE_TIME         = ${current.TIME}
     , CHANGE_USER_ID      = ${session.ID}  
     , ACCEPT_USER_ID      = ${ACCEPT_USER_ID}
     , ACCEPT_DATE         = ${ACCEPT_DATE} 
     , ACCEPT_TIME         = ${ACCEPT_TIME} 
     , ACCEPT_REASON       = ${ACCEPT_REASON} 
 WHERE HOUSE_CODE = ${session.HOUSE_CODE} 
       AND COMPANY_CODE = ${SEPOA_APPROVAL_S_COMPANY_CODE} 
       AND APP_NO = ${APP_NO} 
       AND APP_NO_SEQ = ${APP_NO_SEQ} 
       AND CAST(NVL(APP_LINE_SEQ,'999') AS INT) > CAST(NVL(${APP_LINE_SEQ},'999') AS INT)


DELETE FROM SGWGL 
 WHERE HOUSE_CODE = ${session.HOUSE_CODE} 
       AND COMPANY_CODE = ${SEPOA_APPROVAL_S_COMPANY_CODE} 
       AND APP_NO = ${APP_NO} 
       AND APP_NO_SEQ = ${APP_NO_SEQ}


DELETE FROM SGWLN 
 WHERE HOUSE_CODE = ${session.HOUSE_CODE} 
       AND COMPANY_CODE = ${SEPOA_APPROVAL_S_COMPANY_CODE} 
       AND APP_NO = ${APP_NO} 
       AND APP_NO_SEQ = ${APP_NO_SEQ}
